from IQEngine.interface import AbstractFrontendValidator
from IQEngine.utils import user_log
from IQEngine.const import RunType
class TimeValidator(AbstractFrontendValidator):
    def __init__(self, engine):
        self._engine = engine
    def can_submit_order(self, account, order):
        asset = order.asset
        if asset.is_listing(self._engine.calendar_dt):
            if self._engine.config.strategy.run_type == RunType.BACKTEST:
                if asset.is_backtest_trading_time(self._engine.trading_dt):
                    return True
                else:
                    user_log.warning('{}的订单不在交易时间段内，下单失败'.format(order.symbol))
                    return False
            elif self._engine.config.strategy.run_type == RunType.TRADING:
                if asset.is_trading_time(self._engine.trading_dt) or asset.is_auction_time(self._engine.trading_dt):
                    return True
                else:
                    user_log.warning('{}的订单不在交易时间段内，下单失败'.format(order.symbol))
                    return False
            else:
                user_log.warning('{}的订单不在交易时间段内，下单失败'.format(order.symbol))
                return False
        else:
            user_log.warning('{}未上市或已经退市，下单失败'.format(order.symbol))
            return False
    def can_cancel_order(self, account, order):
        asset = order.asset
        if not asset.is_can_auction_cancel_time(self._engine.trading_dt):
            if asset.is_trading_time(self._engine.trading_dt) and asset.is_listing(self._engine.calendar_dt):
                return True
            else:
                user_log.warning('{}于{}不允许撤单'.format(order.symbol, self._engine.trading_dt.strftime('%Y-%m-%d %H:%M:%S')))
                return False
